-- =============================================================================
-- Arbiter — DB initialization script
-- Drops legacy + current tables, recreates a clean schema, and seeds test data.
--
-- Usage:
--   docker exec -i arbiter-postgres-1 psql -U arbiter -d arbiter < db/init.sql
-- =============================================================================

-- Aligns the DB's collation version with the container OS's. Without this, if the
-- Postgres image's libc changed since the volume was created, every connection logs a
-- "collation version mismatch" WARNING. Outside BEGIN: ALTER DATABASE is its own transaction.
ALTER DATABASE arbiter REFRESH COLLATION VERSION;

BEGIN;

-- ─── Drop legacy + current tables ────────────────────────────────────────────
DROP TABLE IF EXISTS adjunto CASCADE;
DROP TABLE IF EXISTS claim CASCADE;
DROP TABLE IF EXISTS clasificacion_log CASCADE;
DROP TABLE IF EXISTS siniestro CASCADE;
DROP TABLE IF EXISTS classification_log CASCADE;
DROP TABLE IF EXISTS image_analysis CASCADE;
DROP TABLE IF EXISTS image_embedding CASCADE;
DROP TABLE IF EXISTS risk_analysis CASCADE;
DROP TABLE IF EXISTS rule_result CASCADE;
DROP TABLE IF EXISTS scoring_configuration_history CASCADE;
DROP TABLE IF EXISTS score_band CASCADE;
DROP TABLE IF EXISTS factor_weight CASCADE;
DROP TABLE IF EXISTS scoring_configuration CASCADE;
DROP TABLE IF EXISTS factor CASCADE;
DROP TABLE IF EXISTS insurer_rule_history CASCADE;
DROP TABLE IF EXISTS insurer_rule CASCADE;
DROP TABLE IF EXISTS insurer_claim_cause CASCADE;
DROP TABLE IF EXISTS insurer CASCADE;
DROP TABLE IF EXISTS document_requirement CASCADE;
DROP TABLE IF EXISTS case_state CASCADE;
DROP TABLE IF EXISTS rule CASCADE;
DROP TABLE IF EXISTS claim_cause CASCADE;
DROP TABLE IF EXISTS branch CASCADE;
DROP TABLE IF EXISTS user_insurer CASCADE;
DROP TABLE IF EXISTS user_role CASCADE;
DROP TABLE IF EXISTS role_permission CASCADE;
DROP TABLE IF EXISTS permission CASCADE;
DROP TABLE IF EXISTS role CASCADE;
DROP TABLE IF EXISTS notification CASCADE;
DROP TABLE IF EXISTS damaged_item CASCADE;
DROP TABLE IF EXISTS policy CASCADE;
DROP TABLE IF EXISTS policy_query CASCADE;
DROP TABLE IF EXISTS coverage CASCADE;
DROP TABLE IF EXISTS case_status_history CASCADE;
DROP TABLE IF EXISTS case_documents CASCADE;
DROP TABLE IF EXISTS cases CASCADE;
DROP TABLE IF EXISTS metric CASCADE;
DROP TABLE IF EXISTS insurer_agreement CASCADE;
DROP TABLE IF EXISTS insurer_representative CASCADE;
DROP TABLE IF EXISTS claims_analyst CASCADE;
DROP TABLE IF EXISTS insured CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- ─── users (auth-service) ────────────────────────────────────────────────────
-- H0001 - Login. Credentials are validated against Auth0; profile fields (rol, sector,
-- insured_id) live here (see CLAUDE.md, decision #8).
CREATE TABLE users (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email           VARCHAR(255) NOT NULL UNIQUE,
    password_hash   VARCHAR(255) NOT NULL,
    nombre          VARCHAR(255) NOT NULL,
    apellido        VARCHAR(255) NOT NULL,
    rol             VARCHAR(40)  NOT NULL,
    sector          VARCHAR(255),
    fecha_ingreso   DATE,
    insured_id      VARCHAR(255),
    failed_attempts INTEGER      NOT NULL DEFAULT 0,
    locked_until    TIMESTAMPTZ,
    -- Sign-up doesn't set a password — the user picks one via this invite token (emailed
    -- link, expires in 48h). While set, the user is "pending" and doesn't exist in Auth0
    -- yet (see UserService.createUser/activateAccount).
    invite_token       VARCHAR(255) UNIQUE,
    invite_expires_at  TIMESTAMPTZ,
    -- True forever once initial activation completes — unlike invite_token, a later
    -- password reset doesn't touch it. Sole source of truth for "Pending" vs "Active" in
    -- the referente's panel.
    activated       BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT users_rol_check CHECK (
        rol IN ('ASEGURADO', 'ANALISTA_SINIESTROS', 'REFERENTE_ASEGURADORA')
    )
);

-- ─── insured (auth-service) ────────────────────────────────────────────────────
-- Target shape for what users.insured_id anticipates ("alta de asegurados" — a
-- separate, not-yet-built flow; see the Javadoc on Insured). Not wired up yet.
CREATE TABLE insured (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255) NOT NULL,
    last_name   VARCHAR(255) NOT NULL,
    dni         VARCHAR(20)  NOT NULL UNIQUE,
    email       VARCHAR(255),
    phone       VARCHAR(50),
    case_count  INTEGER,
    user_id     BIGINT       NOT NULL REFERENCES users(id) UNIQUE,
    pep         BOOLEAN      NOT NULL DEFAULT FALSE
);

-- ─── insurer_representative, claims_analyst (auth-service) ────────────────────
-- Profile tables for REFERENTE_ASEGURADORA/ANALISTA_SINIESTROS accounts, duplicating
-- name/last name (+email) that already live on users. Not wired up yet — the Usuarios
-- admin screen still reads straight off users. No insurer_id here (matches the DER):
-- that relationship is user_insurer, not a field on these.
CREATE TABLE insurer_representative (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255),
    last_name   VARCHAR(255),
    user_id     BIGINT NOT NULL UNIQUE REFERENCES users(id)
);

CREATE TABLE claims_analyst (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255),
    last_name   VARCHAR(255),
    email       VARCHAR(255),
    user_id     BIGINT NOT NULL UNIQUE REFERENCES users(id)
);

-- ─── role, permission, role_permission, user_role (auth-service) ─────────────
-- Granular RBAC catalog, additive to users.rol (see the Javadoc on User.roles).
-- role_permission stays empty for now — no permission catalog has been defined yet,
-- seeding fake ones here would just be made-up data.
CREATE TABLE role (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code    VARCHAR(80)  NOT NULL UNIQUE,
    name    VARCHAR(255) NOT NULL
);

CREATE TABLE permission (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name    VARCHAR(255) NOT NULL UNIQUE
);

CREATE TABLE role_permission (
    role_id       BIGINT NOT NULL REFERENCES role(id),
    permission_id BIGINT NOT NULL REFERENCES permission(id),
    PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE user_role (
    user_id BIGINT NOT NULL REFERENCES users(id),
    role_id BIGINT NOT NULL REFERENCES role(id),
    PRIMARY KEY (user_id, role_id)
);

-- insurer_id is a logical reference to rules-service's insurer(id) — cross-module, no
-- real FK, same criterion as classification_log.case_id.
CREATE TABLE user_insurer (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES users(id),
    insurer_id  BIGINT NOT NULL,

    CONSTRAINT user_insurer_user_insurer_unique UNIQUE (user_id, insurer_id)
);

-- ─── cases (cases-service) ───────────────────────────────────────────────────
CREATE TABLE cases (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    branch                  VARCHAR(255) NOT NULL,
    product                 VARCHAR(255) NOT NULL,
    claim_cause             VARCHAR(255) NOT NULL,
    insured_item            VARCHAR(255) NOT NULL,
    insured_id              VARCHAR(255) NOT NULL,
    insured_name            VARCHAR(255),
    policy_number           VARCHAR(255) NOT NULL,
    description             TEXT         NOT NULL,
    event_date              TIMESTAMP(6) NOT NULL,
    event_location          VARCHAR(255) NOT NULL,
    claimed_amount          NUMERIC(38,2),
    pep                     BOOLEAN      NOT NULL DEFAULT FALSE,
    image_consent           BOOLEAN      NOT NULL DEFAULT FALSE,
    contact_email           VARCHAR(255),
    contact_phone           VARCHAR(50),
    status                  VARCHAR(40)  NOT NULL,
    analysis_classification VARCHAR(40),
    analysis_confidence     DOUBLE PRECISION,
    analysis_detail         TEXT,
    deterministic_fast_track BOOLEAN,
    risk_score              DOUBLE PRECISION,
    risk_band               VARCHAR(20),
    risk_breakdown          TEXT,
    forensic_report         TEXT,
    manual_adjustment_note  TEXT,
    classification_attempts INTEGER      NOT NULL DEFAULT 0,
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_cases_risk_band ON cases (risk_band);

-- ─── coverage, policy, policy_query (cases-service) ───────────────────────────
-- Local snapshot-sync target for insurer data (CLAUDE.md decision #10). Today
-- PolicyController/PolicyService read live from InsurerAdapter — none of this replaces
-- that yet. insured_id is a logical reference (auth-service, cross-module) — no real FK.
CREATE TABLE coverage (
    id                              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                            VARCHAR(255) NOT NULL,
    description                     TEXT,
    report_deadline_hours           BIGINT,
    max_events_per_year             INTEGER,
    covers_household                BOOLEAN      NOT NULL DEFAULT FALSE,
    deductible                      NUMERIC,
    claim_extinguishes_coverage     BOOLEAN      NOT NULL DEFAULT FALSE,
    individual                      BOOLEAN      NOT NULL DEFAULT FALSE,
    waiting_period_days             INTEGER,
    branch_id                       BIGINT
);

CREATE TABLE policy (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    insured_id              BIGINT       NOT NULL,
    external_policy_number  VARCHAR(255) NOT NULL,
    product                 VARCHAR(255),
    insured_amount          NUMERIC,
    current                 BOOLEAN      NOT NULL DEFAULT TRUE,
    synced_at               TIMESTAMPTZ,
    coverage_id             BIGINT REFERENCES coverage(id)
);

-- Point-in-time query log against the insurer's DB — distinct from `policy` (the synced
-- local copy). No caller writes here yet.
CREATE TABLE policy_query (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    external_policy_number  VARCHAR(255) NOT NULL,
    insured_amount          NUMERIC,
    current                 BOOLEAN      NOT NULL DEFAULT TRUE,
    up_to_date              BOOLEAN      NOT NULL DEFAULT TRUE,
    queried_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    insurer_payload         TEXT,
    prior_claims            INTEGER
);

-- ─── case_documents (cases-service) ──────────────────────────────────────────
-- Case attachments: one row per document type per case (upsert by type).
CREATE TABLE case_documents (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id         BIGINT       NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    type            VARCHAR(80)  NOT NULL,
    filename        VARCHAR(255) NOT NULL,
    content_type    VARCHAR(255) NOT NULL,
    content         BYTEA        NOT NULL,
    uploaded_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT case_documents_case_type_unique UNIQUE (case_id, type)
);

-- ─── case_status_history (cases-service) ─────────────────────────────────────
-- Append-only record of every case status transition (audit trail).
CREATE TABLE case_status_history (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id     BIGINT       NOT NULL REFERENCES cases(id) ON DELETE CASCADE,
    from_status VARCHAR(40),
    to_status   VARCHAR(40)  NOT NULL,
    actor       VARCHAR(20)  NOT NULL,
    reason      VARCHAR(255) NOT NULL,
    changed_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- ─── notification (cases-service) ─────────────────────────────────────────────
-- Record of a notification about a case. No sender writes here yet — the
-- status-change emails CLAUDE.md describes are still fire-and-forget, not logged.
-- recipient_id is a logical reference to a user (auth-service, another module).
CREATE TABLE notification (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    recipient_id    BIGINT       NOT NULL,
    sent            BOOLEAN      NOT NULL DEFAULT FALSE,
    read            BOOLEAN      NOT NULL DEFAULT FALSE,
    type            VARCHAR(255) NOT NULL,
    channel         VARCHAR(30),
    sent_at         TIMESTAMPTZ,
    read_at         TIMESTAMPTZ,
    content         TEXT,
    case_id         BIGINT       NOT NULL REFERENCES cases(id) ON DELETE CASCADE
);

-- ─── metric (reports-service) ─────────────────────────────────────────────────
-- Pre-aggregated dashboard values. No aggregation job populates this yet
-- (reports-service was empty scaffolding until this table) — target shape only.
CREATE TABLE metric (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    metric_name     VARCHAR(255)   NOT NULL,
    period_from     DATE           NOT NULL,
    period_to       DATE           NOT NULL,
    value           NUMERIC        NOT NULL,
    granularity     VARCHAR(20)
);

-- ─── classification_log (classification-service) ─────────────────────────────
CREATE TABLE classification_log (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id             BIGINT,
    model               VARCHAR(80),
    prompt_version      VARCHAR(80),
    source              VARCHAR(40)  NOT NULL,
    classification      VARCHAR(40)  NOT NULL,
    confidence          NUMERIC(4,3),
    factors             TEXT         NOT NULL,
    latency_ms          BIGINT,
    forensic_report     TEXT,
    insured_name        VARCHAR(255),
    analyst_id          VARCHAR(80),
    decision            VARCHAR(20),
    decision_timestamp  TIMESTAMPTZ,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT classification_log_classification_check CHECK (
        classification IN (
            'FAST_TRACK',
            'FALTA_DOCUMENTACION',
            'LLM_RECOMIENDA_APROBAR',
            'LLM_NO_RECOMIENDA_APROBAR',
            'LLM_SOLICITA_REVISION_MANUAL'
        )
    )
);

-- ─── image_embedding (classification-service) ────────────────────────────────
-- CLIP embeddings (512 dims) for duplicate-image detection across claims. The
-- `embedding vector(512)` column and its IVFFlat index are NOT created here —
-- PgVectorConfig adds them at startup (see pgvector-init.sql). case_id is a logical
-- reference to cases.id (another module), not a real FK — same as classification_log.case_id.
CREATE TABLE image_embedding (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id             BIGINT,
    attachment_label    VARCHAR(120),
    original_filename   VARCHAR(255),
    model               VARCHAR(80)  NOT NULL,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- ─── image_analysis (classification-service) ──────────────────────────────────
-- "analisis_imagen" in the DER (Bucket B — normalized instead of staying as the
-- forensic_report JSON blob). Adapted: references image_embedding by FK instead of
-- repeating its `embedding vector(512)` column — same image, no reason to store the
-- vector twice, both entities are in this module.
CREATE TABLE image_analysis (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    image_embedding_id          BIGINT         NOT NULL REFERENCES image_embedding(id),
    similarity_score            NUMERIC(5,4),
    similar_image_embedding_id  BIGINT REFERENCES image_embedding(id),
    suspicious                  BOOLEAN        NOT NULL DEFAULT FALSE,
    analyzed_at                 TIMESTAMPTZ    NOT NULL DEFAULT NOW(),
    external_source             VARCHAR(255),
    external_reference          TEXT,
    match_type                  VARCHAR(255),
    external_hash               VARCHAR(255)
);

-- ─── risk_analysis, rule_result (classification-service) ─────────────────────
-- One row per scoring run (risk_analysis) / rule evaluation (rule_result), same
-- append-only pattern as classification_log. Split out of classification_log so risk
-- scoring and claim classification are modeled as separate concerns, per the DER.
-- case_id/rule_id are logical references (no real FK), same criterion as
-- classification_log.case_id.
CREATE TABLE risk_analysis (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    case_id         BIGINT         NOT NULL,
    risk_score      NUMERIC(4,3)   NOT NULL,
    risk_band       VARCHAR(20)    NOT NULL,
    risk_breakdown  TEXT           NOT NULL,
    analyzed_at     TIMESTAMPTZ    NOT NULL DEFAULT NOW()
);

-- No rule engine evaluates into this table yet — stays empty until that engine exists.
CREATE TABLE rule_result (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rule_type           VARCHAR(255)   NOT NULL,
    result              VARCHAR(255)   NOT NULL,
    evaluated_value     VARCHAR(255),
    score_contribution  NUMERIC(5,4),
    evaluated_at        TIMESTAMPTZ    NOT NULL,
    rule_id             BIGINT         NOT NULL,
    case_id             BIGINT         NOT NULL
);

-- ─── branch, claim_cause (rules-service) ───────────────────────────────────────
-- Base rule-engine catalog. No insurer/multi-tenant scoping yet.
CREATE TABLE branch (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name    VARCHAR(255) NOT NULL UNIQUE
);

CREATE TABLE claim_cause (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        VARCHAR(255) NOT NULL,
    branch_id   BIGINT       NOT NULL REFERENCES branch(id)
);

-- ─── document_requirement, case_state (rules-service) ─────────────────────────
-- Target-state shape of CLAUDE.md's "AgendaDocumental" and of a configurable
-- CaseStatus (H0015) — neither drives real behavior yet (see the Javadoc on
-- DocumentRequirement/CaseState for what still hardcodes this today).
CREATE TABLE document_requirement (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    risk_band       VARCHAR(20),
    mandatory       BOOLEAN      NOT NULL DEFAULT TRUE,
    document_type   VARCHAR(255) NOT NULL,
    branch_id       BIGINT       NOT NULL REFERENCES branch(id),
    claim_cause_id  BIGINT       NOT NULL REFERENCES claim_cause(id)
);

CREATE TABLE case_state (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            VARCHAR(255) NOT NULL,
    description     VARCHAR(255),
    insured_state   VARCHAR(255),
    is_final        BOOLEAN      NOT NULL DEFAULT FALSE
);

-- ─── factor, scoring_configuration, factor_weight, score_band,
--     scoring_configuration_history (rules-service) ────────────────────────────
-- Data-driven backing for classification-service's RiskScoringService, which already
-- expects this shape via BusinessRules.ScoringConfig (currently served by
-- MockRulesAdapter — replacing it with a real call to rules-service is separate work,
-- not done here).
CREATE TABLE factor (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name    VARCHAR(255) NOT NULL UNIQUE
);

CREATE TABLE scoring_configuration (
    id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name    VARCHAR(255) NOT NULL,
    active  BOOLEAN      NOT NULL DEFAULT TRUE
);

-- factor_code matches classification-service's RiskFactorIds constants by string, not
-- by FK to `factor` — same loose coupling the DER draws.
CREATE TABLE factor_weight (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    factor_code             VARCHAR(80)  NOT NULL,
    weight                  NUMERIC(4,2) NOT NULL,
    scoring_configuration_id BIGINT      NOT NULL REFERENCES scoring_configuration(id)
);

CREATE TABLE score_band (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    band                    VARCHAR(20)  NOT NULL,
    min_score_inclusive     NUMERIC(4,2) NOT NULL,
    active                  BOOLEAN      NOT NULL DEFAULT TRUE,
    scoring_configuration_id BIGINT      NOT NULL REFERENCES scoring_configuration(id)
);

-- changed_by is a logical reference to a user (auth-service, another module) — no real FK.
CREATE TABLE scoring_configuration_history (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    snapshot_config         TEXT         NOT NULL,
    valid_from              TIMESTAMPTZ  NOT NULL,
    valid_to                TIMESTAMPTZ,
    changed_at              TIMESTAMPTZ  NOT NULL,
    reason                  VARCHAR(255),
    changed_by              BIGINT,
    scoring_configuration_id BIGINT      NOT NULL REFERENCES scoring_configuration(id)
);

-- ─── insurer, insurer_claim_cause, insurer_rule, insurer_rule_history
--     (rules-service) ────────────────────────────────────────────────────────
-- Multi-tenant scoping of the rules catalog: which claim-causes/rules each insurer has
-- enabled and how it customizes them.
CREATE TABLE insurer (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    legal_name      VARCHAR(255) NOT NULL,
    name            VARCHAR(255) NOT NULL,
    tax_id          VARCHAR(20)  NOT NULL UNIQUE,
    active          BOOLEAN      NOT NULL DEFAULT TRUE,
    schema_name     VARCHAR(255)
);

-- coverage_id is a logical reference to cases-service's coverage(id) — cross-module, no
-- real FK.
CREATE TABLE insurer_claim_cause (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    insurer_id          BIGINT NOT NULL REFERENCES insurer(id),
    branch_id           BIGINT NOT NULL REFERENCES branch(id),
    claim_cause_id      BIGINT NOT NULL REFERENCES claim_cause(id),
    coverage_id         BIGINT
);

CREATE TABLE insurer_rule (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    insurer_id          BIGINT       NOT NULL REFERENCES insurer(id),
    active              BOOLEAN      NOT NULL DEFAULT TRUE,
    valid_from          TIMESTAMPTZ  NOT NULL,
    configuration       TEXT,
    name                VARCHAR(255) NOT NULL,
    rule_type           VARCHAR(255) NOT NULL,
    effect              VARCHAR(20),
    priority            INTEGER,
    blocks_fast_track   BOOLEAN      NOT NULL DEFAULT FALSE,
    branch_id           BIGINT       NOT NULL REFERENCES branch(id),
    coverage_id         BIGINT
);

-- changed_by is a logical reference to a user (auth-service, another module) — no real FK.
CREATE TABLE insurer_rule_history (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    config_version  TEXT         NOT NULL,
    changed_at      TIMESTAMPTZ  NOT NULL,
    reason          VARCHAR(255),
    valid_from      TIMESTAMPTZ  NOT NULL,
    valid_to        TIMESTAMPTZ,
    insurer_rule_id BIGINT       NOT NULL REFERENCES insurer_rule(id),
    changed_by      BIGINT
);

-- ─── Seed data: users ───────────────────────────────────────────────────────
