-- ─── Seed data: case_documents ────────────────────────────────────────────────
-- Sample attachments per case. Uses the test PDF (docs/postman/test-docs/denuncia_policial_ambigua.pdf)
-- as base64 content for all of them — in dev what matters is having rows, not real content.
-- The PDF is ~5.6 KB; the same blob is reused to avoid bloating the script.

-- Variable holding the PDF content so the literal isn't repeated in every INSERT.
DO $$
DECLARE
    pdf_content BYTEA := decode('', 'base64');
    -- Test photo of a cracked screen (800x534, ~32 KB). Source: Pexels, photo by
    -- Towfiqu barbhuiya — https://www.pexels.com/photo/cracked-screen-of-a-smartphone-11921157/
    -- Pexels license: free to use, including commercially, no attribution required.
    -- Used to be a 1x1px JPEG: enough to have rows, but the case documentation viewer
    -- rendered it as an empty panel.
    -- Same as the PDF, the same blob is reused across the 3 photos to avoid bloating the script.
    jpg_content BYTEA := decode('', 'base64');
BEGIN
    INSERT INTO case_documents (case_id, type, filename, content_type, content, uploaded_at)
    VALUES
        -- Case 1 (Fast Track, phone theft): complete documentation
        (1, 'police_report', 'denuncia-policial-martinez.pdf', 'application/pdf', pdf_content, '2026-06-29 00:27:10+00'),
        (1, 'item_photo',    'foto-celular-roto.jpg',          'image/jpeg',      jpg_content, '2026-06-29 00:27:10+00'),

        -- Case 2 (LLM does not recommend, suspicious theft): complete documentation
        (2, 'police_report', 'denuncia-policial-gomez.pdf',    'application/pdf', pdf_content, '2026-06-29 01:20:00+00'),
        (2, 'item_photo',    'foto-notebook-danada.jpg',       'image/jpeg',      jpg_content, '2026-06-29 01:20:00+00'),
        (2, 'invoice',       'factura-compra-notebook.pdf',    'application/pdf', pdf_content, '2026-06-29 01:20:00+00'),

        -- Case 3 (missing documentation): only has the police report, missing item_photo
        (3, 'police_report', 'denuncia-policial-lopez.pdf',    'application/pdf', pdf_content, '2026-07-01 22:57:40+00'),

        -- Case 4 (missing documentation, high amount): only has the police report, missing item_photo
        (4, 'police_report', 'denuncia-policial-fernandez.pdf','application/pdf', pdf_content, '2026-07-01 23:24:00+00'),

        -- Case 5 (just submitted): uploaded the item photo, missing the police report
        (5, 'item_photo',    'foto-iphone-roto.jpg',           'image/jpeg',      jpg_content, '2026-07-02 10:00:00+00');
END $$;

-- Reset the sequence
SELECT setval('case_documents_id_seq', (SELECT MAX(id) FROM case_documents));

COMMIT;
